// Rebuild both dependent fixture bundles and compare every generated byte.
import assert from 'node:assert/strict';
import { readdir, readFile } from 'node:fs/promises';
import { execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
const folders = [new URL('./', import.meta.url), new URL('../evidence-sample/', import.meta.url)];
const before = new Map();
for (const folder of folders) {
  for (const name of await readdir(folder)) {
    if (name.endsWith('.json') || ['metadata.mjs', 'SUMMARY.md'].includes(name)) {
      const file = new URL(name, folder);
      before.set(file.href, await readFile(file));
    }
  }
}
for (const folder of folders) execFileSync(process.execPath, [fileURLToPath(new URL('build.mjs', folder))], {stdio:'inherit'});
for (const [file, bytes] of before) assert.deepEqual(await readFile(new URL(file)), bytes, `stale or non-deterministic: ${file}`);
console.log(`${before.size} generated files reproduce byte-for-byte.`);
